import React, { useEffect, useState } from 'react';
import { db, collection, query, orderBy, onSnapshot, deleteDoc, doc } from '../firebase';
import { InspectionData } from '../types';
import { Trash2, Search, Calendar, User, Box, Activity, FileText, Download } from 'lucide-react';

export const InspectionHistory: React.FC = () => {
  const [inspections, setInspections] = useState<InspectionData[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    const q = query(collection(db, "inspections"), orderBy("createdAt", "desc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      } as InspectionData));
      setInspections(data);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handleDelete = async (id: string) => {
    if (window.confirm("Are you sure you want to delete this record?")) {
      try {
        await deleteDoc(doc(db, "inspections", id));
      } catch (err) {
        console.error("Error deleting document: ", err);
      }
    }
  };

  const handleExport = () => {
    if (inspections.length === 0) {
      alert("No data available to export.");
      return;
    }

    // CSV Headers
    const headers = ['Date', 'Tester', 'Pipe Grade', 'Lot Number', 'Roughness Score (Ra)'];

    // Process rows - handling potential commas by wrapping in quotes and escaping existing quotes
    const rows = inspections.map(item => [
      item.date,
      `"${item.tester.replace(/"/g, '""')}"`,
      `"${item.grade.replace(/"/g, '""')}"`,
      `"${item.lot.replace(/"/g, '""')}"`,
      item.rating
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(r => r.join(','))
    ].join('\n');

    // Add BOM (Byte Order Mark) for Excel to recognize UTF-8 correctly
    const blob = new Blob([`\ufeff${csvContent}`], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `pipe_inspections_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const filteredInspections = inspections.filter(item => 
    item.tester.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.lot.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.grade.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
        <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
            <FileText className="w-6 h-6 text-blue-600"/>
            History Log
        </h2>
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
          <button 
            onClick={handleExport}
            disabled={inspections.length === 0}
            className="flex items-center justify-center gap-2 bg-emerald-600 hover:bg-emerald-700 disabled:bg-gray-200 disabled:text-gray-400 text-white px-4 py-2.5 rounded-lg font-semibold transition-all shadow-sm active:scale-95"
            title="Export data to CSV for Excel"
          >
            <Download className="w-4 h-4" />
            Export Excel
          </button>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input 
              type="text" 
              placeholder="Search logs..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10 pr-4 py-2.5 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 w-full lg:w-64 outline-none bg-white shadow-sm"
            />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {filteredInspections.length === 0 ? (
           <div className="text-center py-12 bg-white rounded-xl shadow-sm border-2 border-dashed border-gray-200">
             <div className="bg-gray-50 p-4 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                <Box className="w-8 h-8 text-gray-300" />
             </div>
             <p className="text-gray-500 text-lg">No records found</p>
           </div>
        ) : (
          filteredInspections.map((item) => (
            <div key={item.id} className="bg-white p-5 rounded-xl shadow-sm border border-gray-100 hover:shadow-md transition-shadow group relative">
                <button 
                  onClick={() => item.id && handleDelete(item.id)}
                  className="absolute top-4 right-4 p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-full opacity-0 group-hover:opacity-100 transition-all z-10"
                  title="Delete Record"
                >
                  <Trash2 className="w-5 h-5" />
                </button>

                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                    <div className="space-y-1">
                        <div className="flex items-center gap-2 text-sm text-gray-500 mb-1">
                           <Calendar className="w-4 h-4" />
                           <span>{item.date}</span>
                           <span className="text-gray-300">|</span>
                           <User className="w-4 h-4" />
                           <span className="font-medium text-gray-700">{item.tester}</span>
                        </div>
                        <div className="flex items-center gap-3">
                           <h3 className="text-lg font-bold text-gray-900">{item.lot}</h3>
                           <span className="bg-gray-100 text-gray-600 px-2 py-0.5 rounded text-xs font-semibold uppercase tracking-wider border border-gray-200">
                             {item.grade}
                           </span>
                        </div>
                    </div>

                    <div className="flex items-center gap-4 mt-2 sm:mt-0">
                        <div className="text-right">
                            <p className="text-xs text-gray-500 uppercase font-semibold">Score</p>
                            <div className={`text-2xl font-bold flex items-center gap-1 justify-end
                                ${item.rating <= 2 ? 'text-green-600' : item.rating === 3 ? 'text-orange-500' : 'text-red-600'}
                            `}>
                                <Activity className="w-5 h-5" />
                                {item.rating}
                            </div>
                        </div>
                        <div className={`w-2 h-12 rounded-full hidden sm:block
                             ${item.rating <= 2 ? 'bg-green-500' : item.rating === 3 ? 'bg-orange-500' : 'bg-red-500'}
                        `}></div>
                    </div>
                </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { InspectionForm } from './components/InspectionForm';
import { InspectionHistory } from './components/InspectionHistory';
import { AnalyticsDashboard } from './components/AnalyticsDashboard';
import { LayoutDashboard, PlusCircle, History, GripHorizontal, WifiOff } from 'lucide-react';

