import React, { useEffect, useState, useMemo } from 'react';
import { db, collection, query, orderBy, onSnapshot } from '../firebase';
import { InspectionData } from '../types';
import { Filter, BarChart2, ScatterChart, Settings2, Download } from 'lucide-react';

// --- Statistical Helper Functions ---
const calculateMean = (values: number[]) => {
  if (values.length === 0) return 0;
  return values.reduce((a, b) => a + b, 0) / values.length;
};

const calculateMedian = (values: number[]) => {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
};

const calculateMode = (values: number[]) => {
  if (values.length === 0) return 0;
  const counts: Record<number, number> = {};
  let maxFreq = 0;
  let mode = values[0];
  values.forEach(v => {
    counts[v] = (counts[v] || 0) + 1;
    if (counts[v] > maxFreq) {
      maxFreq = counts[v];
      mode = v;
    }
  });
  return mode;
};

const calculateQuartiles = (values: number[]) => {
  const sorted = [...values].sort((a, b) => a - b);
  const min = sorted[0];
  const max = sorted[sorted.length - 1];
  const median = calculateMedian(sorted);

  const mid = Math.floor(sorted.length / 2);
  const lowerHalf = sorted.slice(0, mid);
  const upperHalf = sorted.length % 2 === 0 ? sorted.slice(mid) : sorted.slice(mid + 1);

  const q1 = calculateMedian(lowerHalf);
  const q3 = calculateMedian(upperHalf);

  return { min, q1, median, q3, max };
};

// --- Types ---
type ChartType = 'box' | 'scatter' | 'combined';

export const AnalyticsDashboard: React.FC = () => {
  const [data, setData] = useState<InspectionData[]>([]);
  const [loading, setLoading] = useState(true);

  // Filters & Controls
  const [selectedTester, setSelectedTester] = useState<string>('All');
  const [selectedGrade, setSelectedGrade] = useState<string>('All');
  const [chartType, setChartType] = useState<ChartType>('combined');

  useEffect(() => {
    const q = query(collection(db, "inspections"), orderBy("createdAt", "asc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const rawData = snapshot.docs.map(doc => ({
         ...doc.data()
      } as InspectionData));
      setData(rawData);
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // --- Derived Data ---
  const uniqueTesters = useMemo(() => Array.from(new Set(data.map(d => d.tester))), [data]);
  const uniqueGrades = useMemo(() => Array.from(new Set(data.map(d => d.grade))), [data]);

  const filteredData = useMemo(() => {
    return data.filter(d => {
      const matchTester = selectedTester === 'All' || d.tester === selectedTester;
      const matchGrade = selectedGrade === 'All' || d.grade === selectedGrade;
      return matchTester && matchGrade;
    });
  }, [data, selectedTester, selectedGrade]);

  const overallStats = useMemo(() => {
    const ratings = filteredData.map(d => d.rating);
    return {
      mean: calculateMean(ratings),
      median: calculateMedian(ratings),
      mode: calculateMode(ratings),
      count: ratings.length
    };
  }, [filteredData]);

  const chartData = useMemo(() => {
    // Group by Lot
    const groupedByLot: Record<string, number[]> = {};
    const lotDetails: Record<string, { grade: string }> = {}; // Store extra meta for tooltip if needed

    filteredData.forEach(d => {
      if (!groupedByLot[d.lot]) groupedByLot[d.lot] = [];
      groupedByLot[d.lot].push(d.rating);
      lotDetails[d.lot] = { grade: d.grade };
    });

    return Object.keys(groupedByLot).map(lot => {
      const values = groupedByLot[lot];
      const stats = calculateQuartiles(values);
      const mean = calculateMean(values);
      return {
        lot,
        values, // for scatter
        ...stats, // min, q1, median, q3, max
        mean,
        grade: lotDetails[lot].grade
      };
    });
  }, [filteredData]);

  if (loading) return <div className="h-64 flex items-center justify-center text-gray-400">Loading Analytics...</div>;

  return (
    <div className="space-y-6">

      {/* 1. Controls Section */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex flex-col md:flex-row gap-3">
           <div className="relative">
             <Filter className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
             <select 
                value={selectedGrade}
                onChange={(e) => setSelectedGrade(e.target.value)}
                className="pl-9 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm font-medium text-gray-700 outline-none focus:ring-2 focus:ring-blue-500"
             >
               <option value="All">All Grades</option>
               {uniqueGrades.map(g => <option key={g} value={g}>{g}</option>)}
             </select>
           </div>

           <div className="relative">
             <Filter className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
             <select 
                value={selectedTester}
                onChange={(e) => setSelectedTester(e.target.value)}
                className="pl-9 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm font-medium text-gray-700 outline-none focus:ring-2 focus:ring-blue-500 max-w-[200px]"
             >
               <option value="All">All Testers</option>
               {uniqueTesters.map(t => <option key={t} value={t}>{t}</option>)}
             </select>
           </div>
        </div>

        <div className="flex bg-gray-100 p-1 rounded-lg self-start md:self-auto">
          <button 
            onClick={() => setChartType('scatter')}
            className={`px-3 py-1.5 rounded-md text-sm font-medium transition-all flex items-center gap-2 ${chartType === 'scatter' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
          >
            <ScatterChart className="w-4 h-4" /> Scatter
          </button>
          <button 
            onClick={() => setChartType('box')}
            className={`px-3 py-1.5 rounded-md text-sm font-medium transition-all flex items-center gap-2 ${chartType === 'box' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
          >
            <BarChart2 className="w-4 h-4" /> Box Plot
          </button>
          <button 
            onClick={() => setChartType('combined')}
            className={`px-3 py-1.5 rounded-md text-sm font-medium transition-all flex items-center gap-2 ${chartType === 'combined' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
          >
            <Settings2 className="w-4 h-4" /> Combined
          </button>
        </div>
      </div>

      {/* 2. Summary Statistics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
         <StatCard label="Total Inspections" value={overallStats.count} color="blue" />
         <StatCard label="Average (Mean)" value={overallStats.mean.toFixed(2)} color="emerald" subtext="Arithmetic Average" />
         <StatCard label="Median Score" value={overallStats.median.toFixed(2)} color="indigo" subtext="Middle Value" />
         <StatCard label="Mode Score" value={overallStats.mode} color="purple" subtext="Most Frequent" />
      </div>

      {/* 3. Advanced Chart */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        <h3 className="text-lg font-bold text-gray-800 mb-2">Process Control Analysis</h3>
        <p className="text-sm text-gray-500 mb-6">Distribution of roughness scores by Lot Number.</p>

        <div className="w-full overflow-x-auto">
          <div className="min-w-[800px] h-[450px]">
             {chartData.length > 0 ? (
               <BoxScatterChart data={chartData} type={chartType} />
             ) : (
               <div className="h-full flex items-center justify-center text-gray-400">
                 No data found for selected filters.
               </div>
             )}
          </div>
        </div>
      </div>

    </div>
  );
};

// --- Sub-components ---

const StatCard = ({ label, value, color, subtext }: { label: string, value: string | number, color: string, subtext?: string }) => {
  const colors: Record<string, string> = {
    blue: 'bg-blue-50 text-blue-700 border-blue-100',
    emerald: 'bg-emerald-50 text-emerald-700 border-emerald-100',
