};

// --- SVG Chart Component ---
interface ChartDataPoint {
  lot: string;
  values: number[];
  min: number;
  q1: number;
  median: number;
  q3: number;
  max: number;
  mean: number;
}

const BoxScatterChart = ({ data, type }: { data: ChartDataPoint[], type: ChartType }) => {
  const chartHeight = 400;
  const padding = { top: 20, right: 30, bottom: 80, left: 50 };
  const graphWidth = Math.max(800, data.length * 80); // Dynamic width
  const graphHeight = chartHeight - padding.top - padding.bottom;

  // Scale Y: Map 1-5 to pixel height
  const scaleY = (val: number) => graphHeight - ((val - 0.5) / 5) * graphHeight;

  // Render
  return (
    <svg width="100%" height={chartHeight} viewBox={`0 0 ${graphWidth + padding.left + padding.right} ${chartHeight}`} className="overflow-visible">
      <g transform={`translate(${padding.left}, ${padding.top})`}>

        {/* Grid Lines Y */}
        {[1, 2, 3, 4, 5].map(tick => (
          <g key={tick}>
            <line x1={0} y1={scaleY(tick)} x2={graphWidth} y2={scaleY(tick)} stroke="#e5e7eb" strokeDasharray="3 3" />
            <text x={-10} y={scaleY(tick)} dy="0.32em" textAnchor="end" fontSize="12" fill="#6b7280">{tick}</text>
          </g>
        ))}

        {/* X Axis Line */}
        <line x1={0} y1={graphHeight} x2={graphWidth} y2={graphHeight} stroke="#9ca3af" />

        {/* Data Loop */}
        {data.map((item, index) => {
          const xCenter = (index + 0.5) * (graphWidth / data.length);
          const boxWidth = (graphWidth / data.length) * 0.4;

          return (
            <g key={item.lot}>

              {/* Box Plot Layer */}
              {(type === 'box' || type === 'combined') && (
                <g>
                   {/* Whiskers (Min to Max) */}
                   <line x1={xCenter} y1={scaleY(item.min)} x2={xCenter} y2={scaleY(item.max)} stroke="#1f2937" strokeWidth="2" />
                   <line x1={xCenter - boxWidth/2} y1={scaleY(item.min)} x2={xCenter + boxWidth/2} y2={scaleY(item.min)} stroke="#1f2937" strokeWidth="2" />
                   <line x1={xCenter - boxWidth/2} y1={scaleY(item.max)} x2={xCenter + boxWidth/2} y2={scaleY(item.max)} stroke="#1f2937" strokeWidth="2" />

                   {/* Box (Q1 to Q3) */}
                   <rect 
                     x={xCenter - boxWidth/2} 
                     y={Math.min(scaleY(item.q1), scaleY(item.q3))} 
                     width={boxWidth} 
                     height={Math.abs(scaleY(item.q3) - scaleY(item.q1)) || 2} // Ensure minimal height if q1==q3
                     fill="#6b7280" 
                     fillOpacity="0.5" 
                     stroke="#1f2937" 
                     strokeWidth="2" 
                   />

                   {/* Median Line */}
                   <line 
                     x1={xCenter - boxWidth/2} 
                     y1={scaleY(item.median)} 
                     x2={xCenter + boxWidth/2} 
                     y2={scaleY(item.median)} 
                     stroke="#fff" 
                     strokeWidth="2" 
                   />
                </g>
              )}

              {/* Jitter Scatter Layer */}
              {(type === 'scatter' || type === 'combined') && (
                <g>
                  {item.values.map((val, i) => {
                    // Psuedo-random jitter based on value and index
                    const jitter = (Math.sin(i * 999) * boxWidth * 0.4); 
                    return (
                      <circle 
                        key={i} 
                        cx={xCenter + jitter} 
                        cy={scaleY(val)} 
                        r={4} 
                        fill={
                           val <= 2 ? '#22c55e' : 
                           val === 3 ? '#f97316' : '#ef4444'
                        }
                        fillOpacity="0.7"
                        stroke="white"
                        strokeWidth="1"
                      />
                    );
                  })}
                </g>
              )}

              {/* Mean Marker (Triangle) */}
              <path 
                d={`M ${xCenter} ${scaleY(item.mean) - 8} L ${xCenter + 6} ${scaleY(item.mean) + 4} L ${xCenter - 6} ${scaleY(item.mean) + 4} Z`}
                fill="#059669"
                stroke="white"
                strokeWidth="1"
              />
              <text x={xCenter} y={scaleY(item.mean) - 12} textAnchor="middle" fontSize="10" fill="#059669" fontWeight="bold">
                {item.mean.toFixed(2)}
              </text>

              {/* X Axis Labels */}
              <text 
                x={0} 
                y={0} 
                transform={`translate(${xCenter}, ${graphHeight + 15}) rotate(-90)`} 
                textAnchor="end" 
                fontSize="12" 
                fill="#374151"
                fontWeight="500"
              >
                {item.lot}
              </text>

            </g>
          );
        })}
      </g>
    </svg>
  );
};

