          {selected.length === 0 
            ? `All ${label}s` 
            : `${selected.length} ${label}${selected.length > 1 ? 's' : ''}`}
        </span>
        <ChevronDown className={`w-4 h-4 ml-2 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      {isOpen && (
        <div className="absolute z-50 w-56 mt-2 right-0 bg-white border border-gray-200 rounded-xl shadow-xl max-h-64 overflow-y-auto animate-fade-in">
          <div className="p-2 border-b border-gray-100 sticky top-0 bg-white z-10 flex justify-between">
            <button 
              onClick={() => onChange([])} // Clear to select all effectively
              className="text-xs font-semibold text-gray-500 hover:bg-gray-100 px-2 py-1 rounded"
            >
              Reset
            </button>
          </div>
          <div className="p-2 space-y-1">
            {options.map(option => {
              const isSelected = selected.includes(option);
              return (
                <div 
                  key={option} 
                  onClick={() => toggleOption(option)}
                  className={`flex items-center gap-3 px-3 py-2 rounded-lg cursor-pointer transition-colors text-sm
                    ${isSelected ? 'bg-blue-50 text-blue-700' : 'hover:bg-gray-50 text-gray-700'}
                  `}
                >
                  <div className={`w-4 h-4 rounded border flex items-center justify-center transition-colors
                    ${isSelected ? 'bg-blue-600 border-blue-600' : 'border-gray-300 bg-white'}
                  `}>
                    {isSelected && <Check className="w-3 h-3 text-white" />}
                  </div>
                  <span className="truncate">{option}</span>
                </div>
              );
            })}
            {options.length === 0 && <div className="text-center text-gray-400 py-2 text-xs">No options available</div>}
          </div>
        </div>
      )}
    </div>
  );
};

// --- SVG Tester Coverage Chart ---
interface CoverageDataPoint {
  lot: string;
  grade: string;
  count: number;
  testers: string[];
}

const TesterCoverageChart = ({ data }: { data: CoverageDataPoint[] }) => {
  const chartHeight = 300;
  const padding = { top: 30, right: 30, bottom: 80, left: 50 };
  const graphWidth = Math.max(800, data.length * 80);
  const graphHeight = chartHeight - padding.top - padding.bottom;

  const maxCount = Math.max(Math.max(...data.map(d => d.count)), 3);
  const scaleY = (val: number) => graphHeight - (val / maxCount) * graphHeight;

  return (
    <svg width="100%" height={chartHeight} viewBox={`0 0 ${graphWidth + padding.left + padding.right} ${chartHeight}`} className="overflow-visible">
       <g transform={`translate(${padding.left}, ${padding.top})`}>
          {Array.from({ length: maxCount + 1 }).map((_, i) => (
             <g key={i}>
                <line x1={0} y1={scaleY(i)} x2={graphWidth} y2={scaleY(i)} stroke="#e5e7eb" strokeDasharray="3 3" />
                <text x={-10} y={scaleY(i)} dy="0.32em" textAnchor="end" fontSize="12" fill="#6b7280">{i}</text>
             </g>
          ))}
          <line x1={0} y1={graphHeight} x2={graphWidth} y2={graphHeight} stroke="#9ca3af" />
          {data.map((item, index) => {
             const xCenter = (index + 0.5) * (graphWidth / data.length);
             const barWidth = (graphWidth / data.length) * 0.5;
             const barHeight = graphHeight - scaleY(item.count);

             return (
               <g key={item.lot} className="group">
                  <rect
                    x={xCenter - barWidth / 2}
                    y={scaleY(item.count)}
                    width={barWidth}
                    height={barHeight}
                    fill="#3b82f6"
                    rx="4"
                    className="transition-all duration-300 group-hover:fill-blue-700"
                  />
                  <text 
                    x={xCenter} 
                    y={scaleY(item.count) - 6} 
                    textAnchor="middle" 
                    fontSize="12" 
                    fontWeight="bold" 
                    fill="#3b82f6"
                  >
                    {item.count}
                  </text>
                  <text 
                    x={0} 
                    y={0} 
                    transform={`translate(${xCenter}, ${graphHeight + 15}) rotate(-90)`} 
                    textAnchor="end" 
                    fontSize="12" 
                    fill="#374151"
                    fontWeight="500"
                  >
                    {item.lot}
                  </text>
                  <text 
                    x={0} 
                    y={0} 
                    transform={`translate(${xCenter + 12}, ${graphHeight + 15}) rotate(-90)`} 
                    textAnchor="end" 
                    fontSize="10" 
                    fill="#9ca3af"
                  >
                    {item.grade}
                  </text>
               </g>
             );
          })}
       </g>
    </svg>
  );
};

export const InspectionHistory: React.FC = () => {
