export const InspectionForm: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Helper to get local date string YYYY-MM-DD
  const getLocalDate = () => {
    const today = new Date();
    const year = today.getFullYear();
    const month = String(today.getMonth() + 1).padStart(2, '0');
    const day = String(today.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getLocalTime = () => {
    const now = new Date();
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    return `${hours}:${minutes}`;
  };

  const [formData, setFormData] = useState<Omit<InspectionData, 'id' | 'createdAt'>>({
    tester: '',
    date: getLocalDate(),
    time: getLocalTime(),
    grade: '',
    lot: '',
    rating: 1,
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccess(false);

    try {
      await addDoc(collection(db, "inspections"), {
        ...formData,
        createdAt: Date.now()
      });
      setSuccess(true);
      setFormData({
        tester: '',
        date: getLocalDate(),
        time: getLocalTime(),
        grade: '',
        lot: '',
        rating: 1,
      });
      setTimeout(() => setSuccess(false), 3000);

      // Optional: Scroll to top on mobile after submit
      if (window.innerWidth < 768) {
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }
    } catch (err) {
      console.error("Error adding document: ", err);
      setError("Failed to save data. Please check your connection.");
    } finally {
      setLoading(false);
    }
  };

  // Google Colors for logic
  const getRatingColor = (rating: number) => {
    if (rating <= 2) return 'bg-[#34A853] text-white border-[#34A853]'; // Green
